CREATE OR REPLACE PROCEDURE calculate_apt()
LANGUAGE plpgsql
AS $$
BEGIN
    -- Add apt column if it doesn't exist
    ALTER TABLE cases ADD COLUMN IF NOT EXISTS apt bigint;

    -- Update APT for cases that have a decision day
    UPDATE cases 
    SET apt = (CAST(decisionday AS date) - CAST(recvday AS date))::bigint
    WHERE decisionday IS NOT NULL AND decisionday != 'None';

    -- Set APT to NULL for cases without a decision
    UPDATE cases 
    SET apt = NULL
    WHERE decisionday IS NULL OR decisionday = 'None';
END;
$$;

