    ALTER TABLE cases ADD COLUMN IF NOT EXISTS apt integer;

    FOR rec IN SELECT filekey FROM cases LOOP
        UPDATE cases 
        SET apt = (CAST(decisionday AS date) - CAST(recvday AS date))::integer
        WHERE filekey = rec.filekey AND decisionday IS NOT NULL AND decisionday != 'None';

        UPDATE cases 
        SET apt = NULL
        WHERE filekey = rec.filekey AND (decisionday IS NULL OR decisionday = 'None');
    END LOOP;
END;
$$;

